import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Towards Safe Robot Foundation Models","description":"","frontmatter":{"title":"Towards Safe Robot Foundation Models","arxiv":"2503.07404","date":"2025-03-10","authors":"Maximilian Tölle, Theo Gruner, Daniel Palenicek, Jonas Günster, Puze Liu, Joe Watson, Davide Tateo, Jan Peters","categories":"cs.RO","topics":"通用具身智能, 安全强化学习, 动作空间约束","outline":[2,2]},"headers":[],"relativePath":"papers/2503.07404.md","filePath":"papers/2503.07404.md","lastUpdated":null}'),l={name:"papers/2503.07404.md"};function e(m,s,r,c,i,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="towards-safe-robot-foundation-models" tabindex="-1">Towards Safe Robot Foundation Models <a class="header-anchor" href="#towards-safe-robot-foundation-models" aria-label="Permalink to &quot;Towards Safe Robot Foundation Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.07404" target="_blank" rel="noreferrer">2503.07404</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-10</td></tr><tr><td><strong>作者</strong></td><td>Maximilian Tölle, Theo Gruner, Daniel Palenicek, Jonas Günster, Puze Liu, Joe Watson, Davide Tateo, Jan Peters</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把 ATACOM 的「约束流形切空间映射」做成一层挂在通用策略输出之后的即插即用安全层，让任意 VLA 无需安全微调就能保证状态转移满足解析约束。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">论文性质</p><p>这是一篇 3 页的短文（v1，无后续版本），<strong>全文没有任何数值结果</strong>：唯一的实验证据是 Fig. 2 的两条曲线（最大约束违反量与成功率随微调 checkpoint 变化）。本文按全文撰写，但凡涉及实验的部分只能引用定性结论，不复述任何分数。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人基础模型（RFM / VLA）现在的评价维度几乎全部集中在泛化：能不能跨本体、跨任务、跨场景。安全被默认为不需要单独处理——因为训练数据是人类专家的安全演示，模仿学习出来的策略&quot;应该&quot;也是安全的。</p><p>这个默认假设站不住。行为克隆的策略在遇到训练分布外的观测时会产生任意动作，这是 DAgger 那条线二十年前就讲清楚的协变量偏移问题；而&quot;数据里都是安全的&quot;最多带来一种统计上的保守倾向，不构成任何形式保证。对于会跑到工厂和家庭里的通用策略，这个区别是致命的：一次越界可能就是撞坏机械臂或伤到人。</p><p>本文提出的问题是：能不能不动 RFM 本身，在它的输出后面加一层，使得系统的状态转移<strong>可证明地</strong>满足给定约束？这个提法的价值在于解耦——安全不再是训练目标里一个要调权重的软惩罚项，而是部署时的一个独立模块，谁的策略都能挂。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>控制界解决安全问题的工具很成熟：控制障碍函数（CBF）用一个标量函数的导数条件把安全集变成前向不变集；可达性分析（Hamilton-Jacobi）算出最大可控不变集；shielding 则在符号层面拦截不安全动作。这三类方法的共同结构是「用领域知识构造一个可证明的安全滤波器」。综述文献（Brunke 等 2022、Wabersich 等 2023、Hsu 等 2024）已经把它们统一到同一个框架下。</p><p>那么为什么 RFM 社区没有直接用？作者没有明说，但可以从论文的行文推断出两条原因。第一，这些方法几乎都假定一个低维、结构化的动作空间与已知动力学，而 VLA 的输出是高维关节目标或末端位姿增量，且模型本身是黑箱。第二，更实际的原因是文化差异：RFM 这条线的核心资产是数据与预训练，加入解析先验被视为与&quot;scaling 一切&quot;的路线相悖。本文的立场恰恰是反过来的——他们认为&quot;用系统动力学做推理是保证安全的必要条件&quot;，并明确承认这在 RFM 语境下&quot;看起来反直觉&quot;。</p><p>本文选的工具是 ATACOM（Acting on the Tangent space of the Constraint Manifold），来自同一组作者的前作。相对 CBF，ATACOM 的差别在于它不是在原动作空间里做投影或求解 QP，而是先构造一个安全配置的流形，再让策略直接在该流形的切空间里出动作——安全不是被过滤掉的结果，而是参数化本身自带的性质。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>站在这篇论文之前的时间点，已知的事实有三条。其一，ATACOM 已经在机器人空气曲棍球这个平台上被验证过，能保证安全 RL 训练全程不违反约束。其二，Octo、OpenVLA 这类通用策略是用 BC 在大规模数据上训的，作者自己也观察到它们在空气曲棍球上会撞桌面。其三，给 RFM 做&quot;安全微调&quot;在工程上代价很高，而且每换一个场景就要重做一次。</p><p>把这三条摆在一起，最省力的组合方式就浮出来了：ATACOM 本质上是一个从&quot;任意动作&quot;到&quot;安全动作&quot;的映射 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span></span></span></span>，它并不关心那个&quot;任意动作&quot;是谁产生的——原本是 RL 策略，换成 VLA 的输出在数学上没有任何区别。所以只要 VLA 的输出能被解释成一个作用在控制仿射系统上的控制量，就可以原封不动地套上去。这个 idea 的简洁性正是它的说服力来源，也是它的局限来源。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>安全不该被当成一个要学的东西，而该被当成动作空间的一个坐标选择。如果你先把「所有满足约束的配置」这个集合刻画成一个流形，再让策略的输出只在这个流形的切空间里取值，那么无论策略输出什么，系统都不会离开安全集——不安全的动作在这个坐标系里根本不可表达。于是通用策略负责&quot;往哪走&quot;，安全层负责&quot;怎么走才不出界&quot;，两件事在结构上正交，不需要联合训练。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>论文对系统提了两条要求。<strong>要求 1</strong>：可访问系统状态 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span>，且动力学是控制仿射的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.0833em;"><span class="mord">˙</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">G</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mord mathnormal">a</span></span></span></span>。<strong>要求 2</strong>：安全条件能写成连续可微的不等式约束 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7804em;vertical-align:-0.136em;"></span><span class="mord mathbf">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span>。作者论证 OXE 里的大多数机械臂满足刚体假设从而符合要求 1，而实践者通常知道自己机器人的安全边界从而能写出要求 2。</p><p>以论文的空气曲棍球实验为例走一遍完整链路。任务是把冰球打进球门，约束有三条：末端保持在桌面上、机械臂不与桌子碰撞、关节位置不越限。观测是语言指令 + 场景目标图 + 本体感知（关节位置与速度、冰球位置与速度）。策略用预训练 Octo，在 MuJoCo 仿真与真机上各用 BC 微调过一次——注意<strong>微调数据来自一个不使用 ATACOM 的专家策略</strong>，这一点很关键，说明安全层不需要与数据分布对齐。</p><p>推理时的数据流是：Octo 输出桌面 x-y 平面内的期望末端速度 → IK 转成关节速度 → ATACOM 层把这组关节速度映射为安全的关节速度 → 交给关节空间控制器执行。对照组是把未经映射的关节速度直接送给控制器。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>先补一点背景，因为&quot;切空间&quot;这个词对没接触过约束系统的读者不直观。</p><p>给定一个状态 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 与一组约束 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathbf">0</span></span></span></span>，安全集是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbf">0</span><span class="mclose">}</span></span></span></span>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span></span></span></span> 是一个带边界的区域，不是流形。ATACOM 的第一步是引入松弛变量把不等式变成等式，从而得到一个真正的流形（按 ATACOM 原文 [6, 28] 的构造）：定义 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">c</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">μ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathbf">0</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8304em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathbf">0</span></span></span></span>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathbf">0</span></span></span></span> 定义的解集是一个光滑流形 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">M</span></span></span></span>，而&quot;待在安全集里&quot;等价于&quot;待在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">M</span></span></span></span> 上&quot;。</p><p>第二步是把&quot;待在流形上&quot;翻译成对动作的条件。沿系统轨迹对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 求全导数：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:2.0574em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="mord mathnormal">t</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal">c</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">μ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0962em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.0833em;"><span class="mord">˙</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8623em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">μ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1111em;"><span class="mord">˙</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0962em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal">G</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">a</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8623em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">μ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1111em;"><span class="mord">˙</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord mathbf">0</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0962em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord">/</span><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal">s</span></span></span></span>。这是关于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">μ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1111em;"><span class="mord">˙</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的一个<strong>仿射方程</strong>。它的解集是一个仿射子空间，几何上正是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">M</span></span></span></span> 在点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">μ</span><span class="mclose">)</span></span></span></span> 处的切空间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0385em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">s</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">μ</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mord mathcal">M</span></span></span></span>。任何落在这个子空间里的动作都保证 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 不变，也就保证系统不离开安全集。</p><p>第三步是参数化。取该仿射子空间的一组基（零空间基加一个特解），任意一个自由参数向量都对应一个安全动作。于是就得到了论文里那一行映射：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">a</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">safe</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">G</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord"><span class="mord boldsymbol">a</span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">s</span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">a</span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1052em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight" style="color:#cc0000;"><span class="mord mtight" style="color:#cc0000;">\\textsc</span></span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">a</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord">⋅</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="mclose">)</span></span></span></span></span></p><p>VLA 输出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">a</span></span></span></span></span></span> 在这里的角色不是&quot;控制量&quot;，而是&quot;切空间坐标&quot;。这就是它与 CBF 的本质差别：CBF 是先算出一个不安全动作再把它投影回可行域（需要在线解 QP），ATACOM 是让不安全动作根本无法被表达。</p><p>一个必须点明的边界条件：上述推导是<strong>连续时间</strong>的。真实系统以有限频率离散执行，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 只在一阶意义上被保持，离散步长下会有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的漂移。ATACOM 原文用一个把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 拉回零的收缩项处理这件事，但这意味着&quot;保证&quot;在部署时是一个与控制频率挂钩的近似量。论文没有讨论这一点，而 VLA 的推理频率通常远低于关节控制器。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>只有一个实验：真机空气曲棍球击球任务，在 Octo 微调过程的多个 checkpoint 上评测，对比加不加 ATACOM 层。报告两个量——单条轨迹的最大约束违反量，以及把冰球打进球门的成功率。</p><p>三条结论。第一，加了安全层的 Octo 在推理全程不违反约束；不加的 Octo 严重违反，<strong>尽管微调数据全部是安全的专家演示</strong>。第二，加了安全层后成功率随训练迭代稳定上升，而未加的 Octo 成功率更低。第三，也是最有信息量的一条：未加安全层的 Octo，其约束违反量<strong>随训练时间增加而增加</strong>，并反过来损害了任务表现。</p><p>作者由第一条推出&quot;数据里的安全性不等于策略的安全性&quot;，这个推论是站得住的。由第二条推出&quot;ATACOM 不会产生过度保守的控制&quot;，这个推论要弱得多——微调数据不是用 ATACOM 采的却仍能拿到高成功率，只能说明安全层没有把可行动作压死，不能说明它没有代价，因为全文没有&quot;无约束但同样安全的专家&quot;这个上界作参照。</p><p>需要如实指出的是：整个证据链建立在一张图上，没有任何数值、没有试验次数、没有随机种子、没有延迟测量。论文声称安全层&quot;不引入额外计算负担&quot;，但全文没有一处计时。实验平台、约束集与专家策略全部来自作者自己的前作 [28]，属于主场作战。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：通用策略当前只被按泛化能力评价，安全被默认由&quot;演示数据都是安全的&quot;兜底，而这在协变量偏移下不成立。本文把 ATACOM 的约束流形切空间映射抽出来做成一层挂在任意 VLA 输出之后，因为这个映射本来就与动作的来源无关。代价是两条硬要求：可访问状态 + 控制仿射动力学，以及一组人工写好的连续可微约束。空气曲棍球上的结果显示，安全层完全消除了约束违反，而未加层的 Octo 违反量随微调时间<strong>增加</strong>——这是全文最有价值的观察。但证据只有一张无数值的图、一个任务、一个平台，且平台与约束集都来自作者自己的前作。</p><p><strong>三句话版</strong>：这是一篇立场清晰的短文，主张安全必须靠解析领域知识而非数据规模来保证，并给出了最省力的接法。技术上没有新东西，价值在于把两条互不往来的研究线接上，以及那个&quot;BC 越训越不安全&quot;的负面观察。要变成可用的结论，还差定量评测、多任务验证与对约束完备性的讨论。</p><p><strong>一句话版</strong>：把安全做成动作空间的坐标选择而不是训练目标，是对的方向；但&quot;能写出完整约束&quot;这件事本身，恰恰是它没有解决的那部分。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是<strong>要求 2</strong>：实践者能写出一组连续可微的不等式，<strong>完备地</strong>刻画该场景下所有需要避免的事。</p><p>这个假设在空气曲棍球上是真的成立的——&quot;末端不低于桌面&quot;&quot;连杆不与桌子相交&quot;&quot;关节不越限&quot;这三条在解析上就是穷尽的，因为任务本身是二维的、无接触的、几何完全已知的。但本文的论证目标是通用策略在&quot;从工业应用到家庭任务&quot;的部署，而在家庭场景里危险事件的清单是开放的：打翻热锅、夹到手指、把玻璃杯推下台面、拉扯连着的电线。这些既不是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span> 的、也往往不是当前状态的函数（&quot;锅是热的&quot;不在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 里）、更没法穷举。</p><p>作者自己在结论里承认了这一点：&quot;写出所有场景相关的安全约束可能是一件很繁重的事&quot;，并把用 VLM 自动生成约束列为未来工作。但这就把问题原样递归了下去：安全保证的强度现在等于约束集完备性的强度，而完备性没有任何保证，也没有任何度量。换句话说，本文提供的是<strong>条件性</strong>保证——&quot;在你写对了的前提下不会违反&quot;，而工程上真正致命的失效永远发生在你没写到的那一条上。此外，要求 1 排除了接触主导的动力学（刚体控制仿射假设在碰撞瞬间不成立），而操作任务里绝大多数安全事故恰恰发生在接触期间。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要真机，也不需要复现 Octo。目标是量化&quot;保证&quot;在离散执行下的真实强度。</p><ul><li><strong>数据/环境</strong>：MuJoCo 里一个平面二连杆机械臂，约束为末端 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8304em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>（模拟桌面）与关节限位。</li><li><strong>实现</strong>：按 §6 的推导实现 ATACOM 层（松弛变量 + 切空间基 + 收缩项），策略端不用 VLA，直接用一个随机高斯策略与一个在专家轨迹上 BC 出来的策略各跑一遍——因为安全层的 claim 是与策略无关的。</li><li><strong>测量</strong>：在控制步长 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">10</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">33</span><span class="mclose">}</span></span></span></span> ms 上分别测最大约束违反量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop"><span class="mop">max</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">max</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，每档 200 条 rollout。同时记录到达任务的成功率与每步的额外计算耗时。</li><li><strong>判据</strong>：若违反量在 1 ms 时数值为零、在 33 ms（≈30 Hz，典型 VLA 部署频率）时出现非平凡的正值且随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span></span></span></span> 超线性增长，则说明&quot;保证&quot;是一个受离散化限制的性质，论文的表述需要加上频率条件。若在 33 ms 下仍为零，则该 claim 在实践频率下稳健，这是对论文最有力的补强。这个实验的成本极低，却恰好补上全文缺的那个量化维度。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者可以提两条。</p><p><strong>替代解释：安全层可能只是一个通用的动作收缩正则。</strong> 论文观察到加了安全层后成功率<strong>更高</strong>，这与&quot;安全约束是性能约束&quot;的直觉相反，作者的解释是违反约束本身损害了任务。但还有一个同样自洽的解释：ATACOM 层把 Octo 那些高频、大幅、分布外的动作压回一个几何上合理的子空间，起到了平滑与限幅的作用，而这与&quot;约束流形&quot;这套机制没有关系。判决实验很简单——用一个朴素基线替换 ATACOM：把关节速度直接裁剪到一个保守的箱型区间（不用流形、不用动力学、不用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>），其余完全不变。如果这个裁剪基线同样把违反量压到零、且成功率相当，那么在这个任务上 ATACOM 的全部机制都没有兑现成可观测的收益。</p><p><strong>可预测的失败条件：切空间映射保证不变性，不保证活性（liveness）。</strong> 前向不变性只说&quot;不会离开安全集&quot;，完全不说&quot;能到达目标&quot;。当安全集非凸或有多个不连通分支时，切空间映射会把策略困在当前分支里；当 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0962em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 在某点退化（约束梯度消失或多约束线性相关）时，可用切空间维度骤降，动作被压成零。可预测的后果是死锁：约束违反 0%、成功率 0%。空气曲棍球的安全集是一个简单的凸盒子，恰好完全避开了这类几何。一个有力的反例是把实验换成&quot;末端必须绕过桌面中央一根立柱去击球&quot;——安全集变成非单连通，此时若安全层导致策略在立柱一侧反复徘徊，就说明这套机制在需要&quot;暂时靠近约束边界才能完成任务&quot;的场景里不可用，而这正是家庭操作的常态。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>作者提出的未来方向是&quot;用 VLM 自动写约束&quot;。这是增量的，而且把形式保证的根基交给了一个会幻觉的模型。</p><p><strong>新的 framing</strong>：不要把约束当成人写的规格，也不要当成 VLM 生成的文本，而把<strong>安全动作空间本身当成一个可迁移的预训练资产</strong>——就像 tokenizer 之于语言模型。具体说，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 参数化为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，从跨任务的&quot;人类叫停&quot;数据中学习它，学出来的不是某个场景的约束，而是一个跨场景共享的、把状态映射到安全流形坐标的图册（chart）。VLA 输出的动作直接被解释成这个共享坐标系里的分量。</p><p>(a) <strong>驱动它的局限</strong>：本文的保证强度完全由人写约束的完备性决定，而完备性既不可验证也不可迁移，每换一个场景就要从零重写。(b) <strong>可借鉴的相邻领域工具</strong>：流形学习与黎曼几何里从数据估计约束流形的做法；共形预测（conformal prediction）给出的分布无关覆盖率保证，可以把&quot;学出来的约束&quot;配上一个<strong>校准过的</strong>违反概率上界，从而在&quot;形式保证&quot;与&quot;学习&quot;之间取得一个诚实的中间态；以及交互式模仿学习里的人类干预信号——<a href="/notes/papers/2503.07771">RoboCopilot</a> 那套人在环接管系统产生的正是&quot;人认为这里危险所以接管&quot;的时刻标注，天然是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的监督信号。(c) <strong>第一个实验长什么样</strong>：在 5 个操作任务上收集人类接管时刻，训一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，在第 6 个留出任务上直接套 ATACOM 层，与&quot;该任务的人工解析约束&quot;对比违反率与成功率。判据不是谁更安全，而是<strong>学出来的约束能否在零新增标注的情况下达到人工约束的大部分覆盖</strong>——如果能，安全就第一次具备了与 VLA 同样的 scaling 性质。</p>',55)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
